function createTargetMoment(dateString, timeString) {
    // Parsing complexo, mas encapsulado em uma função auxiliar
    const date = moment(dateString, 'DD/MM/YYYY');
    const [hour, minute] = timeString.split(':');
    return date.set({ hour: parseInt(hour), minute: parseInt(minute) });
